"""Build a completely offline, self-contained executive HTML dashboard."""
from pathlib import Path
import csv,json,html
ROOT=Path(__file__).resolve().parents[1]
def rows(name):
 with (ROOT/'data/marts'/name).open(encoding='utf-8',newline='') as f:return list(csv.DictReader(f))
monthly=rows('monthly.csv');causes=rows('root_causes.csv');vendors=rows('vendors.csv')[:36];cases=rows('sample_for_excel.csv')[:180]
metrics=json.loads((ROOT/'data/marts/metrics.json').read_text())
data={'monthly':monthly,'causes':causes,'vendors':vendors,'cases':cases,'metrics':metrics}
payload=json.dumps(data,separators=(',',':')).replace('</','<\\/')
page=r'''<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ProfitLeak Atlas | Financial Forensics Console</title>
<style>
:root{--bg:#0b1220;--bg2:#101c32;--panel:#16243a;--line:#29364b;--muted:#93a4bb;--white:#f5f7fc;--teal:#4fe0b5;--lime:#b8ff80;--amber:#f1ba72;--red:#ff7384;--blue:#899bff}
*{box-sizing:border-box}body{margin:0;background:linear-gradient(132deg,#08101b 0%,#111d35 59%,#0b1724 100%);color:var(--white);font-family:Inter,ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;font-size:14px}body:before{content:"";position:fixed;top:-150px;right:-200px;width:620px;height:620px;background:radial-gradient(circle,#28745e33,transparent 70%);pointer-events:none}a{color:var(--teal)}
.page{max-width:1460px;margin:auto;padding:28px 40px 70px}.header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #334258;padding-bottom:22px;gap:20px}.mark{display:flex;align-items:center;gap:15px}.symbol{width:49px;height:49px;display:flex;align-items:center;justify-content:center;border:1px solid #66e9bc88;background:#4fe0b512;border-radius:14px;font-size:27px;color:var(--teal);font-weight:900}.brand{font-weight:750;letter-spacing:2.2px;font-size:18px}.brand small{display:block;color:var(--muted);font-size:10px;letter-spacing:3px;margin-top:5px}.status{color:var(--teal);border:1px solid #4fe0b562;padding:8px 13px;border-radius:30px;font-weight:700;font-size:11px}.header-right{display:flex;align-items:center;gap:14px;color:var(--muted);font-size:11px}.hero{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(300px,.7fr);gap:28px;align-items:end;margin:37px 0 28px}.eyebrow{letter-spacing:3px;text-transform:uppercase;color:var(--teal);font-size:11px;font-weight:800}.hero h1{font-size:clamp(34px,5vw,62px);margin:8px 0 10px;font-weight:820;line-height:1.08;letter-spacing:-2px}.hero h1 span{color:var(--teal)}.hero p{color:var(--muted);max-width:660px;line-height:1.8;margin:0}.signal{border-radius:18px;border:1px solid #4fe0b544;padding:21px;background:linear-gradient(100deg,#16463344,#1b314540)}.signal .up{font-size:11px;color:var(--teal);font-weight:700;letter-spacing:2px}.signal .main{font-size:32px;font-weight:800;margin:9px 0}.signal .note{line-height:1.6;color:#b4c3d4;font-size:12px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:28px 0}.metric,.card{border:1px solid #334158;background:linear-gradient(157deg,#17263b,#111e31);border-radius:17px}.metric{padding:22px;min-height:131px;position:relative;overflow:hidden}.metric:before{content:"";height:3px;width:38px;position:absolute;top:0;left:22px;background:var(--teal)}.metric:nth-child(2):before{background:var(--amber)}.metric:nth-child(3):before{background:var(--blue)}.metric:nth-child(4):before{background:var(--red)}.metric .label{color:var(--muted);font-size:10px;font-weight:750;letter-spacing:1.55px;text-transform:uppercase}.metric .value{font-size:28px;letter-spacing:-.8px;margin-top:14px;font-weight:820}.metric .sub{color:var(--muted);font-size:11px;margin-top:8px}.twocol{display:grid;grid-template-columns:minmax(0,1.13fr) minmax(0,.87fr);gap:16px;margin:16px 0}.card{padding:24px;min-width:0}.card-head{display:flex;align-items:start;justify-content:space-between;gap:10px;margin-bottom:22px}.card-head h2{margin:0;font-size:17px;font-weight:750}.card-head small{display:block;color:var(--muted);margin-top:7px;font-size:11px}.chip{display:inline-block;border:1px solid #41516b;color:#becce1;font-size:10px;letter-spacing:1px;padding:7px 10px;border-radius:20px;white-space:nowrap}.chart{width:100%;height:260px}.chart svg{width:100%;height:100%;overflow:visible}.legend{display:flex;gap:20px;font-size:11px;color:var(--muted);margin-top:16px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px;background:var(--teal)}.dot.p{background:var(--blue)}.barRow{display:grid;grid-template-columns:minmax(112px,1fr) minmax(80px,1.65fr) 94px;align-items:center;gap:12px;margin:17px 0}.barRow .name{color:#d6e1ed;font-size:12px}.barbg{height:10px;background:#28384d;border-radius:10px;overflow:hidden}.barbg .fill{height:100%;border-radius:10px;background:linear-gradient(90deg,#39c69e,#82edce)}.barRow .num{text-align:right;color:#eaf4fb;font-weight:800;font-variant-numeric:tabular-nums}.wide{margin-top:16px}.sim-layout{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:center}.slider{accent-color:var(--teal);width:100%;margin:20px 0}.scenario{font-weight:820;font-size:33px;color:var(--teal)}.scenario-note{line-height:1.6;color:var(--muted);font-size:12px}.source{display:grid;grid-template-columns:1fr auto;gap:10px;padding:11px 0;border-top:1px solid #324159;color:#c9d7e5}.source em{font-style:normal;color:var(--teal);font-weight:800}.tablewrap{overflow-x:auto;max-height:490px;overflow-y:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:12px}th{text-align:left;padding:12px;color:var(--muted);background:#1a2a42;font-size:10px;text-transform:uppercase;letter-spacing:1px;position:sticky;top:0;z-index:1}td{padding:13px 12px;border-bottom:1px solid #25354b;color:#dce7f3}tr:hover td{background:#243a52}.money{color:var(--amber);font-weight:750}.pill{font-size:10px;background:#493b3260;color:#ffd6a3;padding:6px 9px;border-radius:20px}.tools{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px}select,input[type=search]{background:#0f1a2c;color:#f4f6ff;border:1px solid #35465c;border-radius:8px;padding:10px;font:inherit;max-width:100%}.fine{color:var(--muted);font-size:11px;line-height:1.7}.footer{margin-top:29px;border-top:1px solid #2e3d54;padding-top:20px;color:var(--muted);display:flex;justify-content:space-between;gap:15px;font-size:11px}.sr{color:var(--teal)}
@media(max-width:980px){.page{padding:24px}.grid4{grid-template-columns:repeat(2,1fr)}.twocol,.hero{grid-template-columns:1fr}}@media(max-width:580px){.grid4{grid-template-columns:1fr}.sim-layout{grid-template-columns:1fr}.header-right{display:none}.hero h1{letter-spacing:-1px}.barRow{grid-template-columns:120px 1fr 68px;gap:7px}.barRow .name,.barRow .num{font-size:10px}.card{padding:17px}}
</style></head><body><div class="page">
<header class="header"><div class="mark"><div class="symbol">◈</div><div class="brand">PROFITLEAK <span style="color:var(--teal)">ATLAS</span><small><a href="__OVERVIEW__">Executive overview</a></small></div></div><div class="header-right"><span>EUROPEAN PROCUREMENT / 2025–2026</span><span class="status">● DEMO / SYNTHETIC</span></div></header>
<section class="hero"><div><div class="eyebrow">Executive intelligence // case study 01</div><h1>Explore payment<br><span>exceptions.</span></h1><p>Filter procurement exceptions, review sample cases and adjust the assumptions behind modeled recovery.</p></div><div class="signal"><div class="up">MODELLED RECOVERABLE VALUE</div><div class="main" id="heroRecovery">€0</div><div class="note">Indicative opportunity before evidence review. No supplier recovery or realized cash is claimed.</div></div></section>
<section class="grid4"><article class="metric"><div class="label">TOTAL PAYMENT SPEND</div><div class="value" id="spend">—</div><div class="sub">Across 22 months • €</div></article><article class="metric"><div class="label">GROSS LEAKAGE EXPOSURE</div><div class="value" id="loss">—</div><div class="sub">Hypothetical, not confirmed</div></article><article class="metric"><div class="label">FLAGGED PAYMENTS</div><div class="value" id="flags">—</div><div class="sub">Includes nonfinancial control risks</div></article><article class="metric"><div class="label">GROSS LEAKAGE RATE</div><div class="value" id="lossrate">—</div><div class="sub">Percentage of total spend</div></article></section>
<section class="twocol"><article class="card"><div class="card-head"><div><h2>Leakage velocity</h2><small>Monthly detected exposure &amp; modeled recoverability (EUR)</small></div><span class="chip">22 MONTH WINDOW</span></div><div class="chart" id="trendChart"></div><div class="legend"><span><i class="dot"></i>Gross leakage</span><span><i class="dot p"></i>Recovery potential</span></div></article><article class="card"><div class="card-head"><div><h2>Exposure by root cause</h2><small>Gross impact by exception class</small></div><span class="chip">CAUSE DRIVERS</span></div><div id="causeBars"></div><div class="fine">Approval fragmentation is a compliance / process risk only; it is not assigned financial loss.</div></article></section>
<section class="twocol"><article class="card"><div class="card-head"><div><h2>Recovery simulation</h2><small>Apply a realization factor to modeled recoverable exposure</small></div><span class="chip">WHAT-IF MODEL</span></div><div class="sim-layout"><div><label class="fine" for="realization">Recovery realization: <strong id="realizeLabel" style="color:var(--white)">75%</strong></label><input class="slider" id="realization" type="range" min="0" max="100" value="75" step="5"><div class="fine">This is scenario sensitivity, not a statistical prediction.</div></div><div><div class="scenario" id="scenarioValue">€0</div><div class="scenario-note">Forecast recovery if this proportion of risk-adjusted cases is actually recovered.</div></div></div></article><article class="card"><div class="card-head"><div><h2>Control intelligence</h2><small>Risk flags versus estimated cash exposure</small></div><span class="chip">DEFENSIBLE ACCOUNTING</span></div><div class="source"><span>Pure approval bypass flags</span><em id="controlOnly">0</em></div><div class="source"><span>Fraud allegations</span><em>0 verified</em></div><div class="source"><span>Confirmed vendor credits</span><em>€0</em></div><div class="fine" style="margin-top:14px">Investigators must validate ledger, receipt, contract versions, bank statements and vendor terms before asserting a loss.</div></article></section>
<section class="card wide"><div class="card-head"><div><h2>Priority vendor exposure</h2><small>Trace a supplier's simulated payment and exception footprint</small></div><span class="chip">TOP 36 VENDORS</span></div><div class="tablewrap" style="max-height:300px"><table><thead><tr><th>Vendor</th><th>Category</th><th>Country</th><th>Payments</th><th>Gross exposure</th><th>Recovery estimate</th></tr></thead><tbody id="vendorRows"></tbody></table></div></section>
<section class="card wide"><div class="card-head"><div><h2>Evidence-led casebook</h2><small>Top 180 cases ranked by exposure. Full evidence export has all flagged payments.</small></div><span class="chip">DRILL-DOWN</span></div><div class="tools"><input id="search" aria-label="Search cases" type="search" placeholder="Search payment ID, vendor or issue..."><select id="issueFilter" aria-label="Filter by exception type"><option value="all">All exception types</option></select></div><div class="tablewrap"><table><thead><tr><th>Payment</th><th>Vendor</th><th>Exception</th><th>Gross exposure</th><th>Modeled recovery</th><th>Suggested validation</th></tr></thead><tbody id="caseRows"></tbody></table></div><p class="fine">This is a synthetic benchmark. Designed rule/label alignment must not be interpreted as real-world precision, recall, or fraud detection accuracy.</p></section>
<footer class="footer"><span>PROFITLEAK ATLAS · Original synthetic implementation · <span class="sr">Evidence first, assumptions explicit</span></span><span>SQL · PYTHON · EXCEL · POWER BI SOURCE</span></footer></div>
<script id="payload" type="application/json">__PAYLOAD__</script>
<script>
const D=JSON.parse(document.getElementById('payload').textContent), euros=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(+n||0),compact=n=>new Intl.NumberFormat('en-IE',{notation:'compact',maximumFractionDigits:2}).format(+n||0),number=n=>new Intl.NumberFormat('en-IE').format(+n||0),escapeHTML=s=>String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const m=D.metrics;document.getElementById('spend').textContent=euros(m.spend_eur);document.getElementById('loss').textContent=euros(m.gross_estimated_loss_eur);document.getElementById('flags').textContent=number(m.flagged_payments);document.getElementById('lossrate').textContent=(100*m.gross_estimated_loss_eur/m.spend_eur).toFixed(2)+'%';document.getElementById('heroRecovery').textContent=euros(m.modeled_recoverable_eur);
const C=D.causes, maxLoss=Math.max(...C.map(x=>+x.gross_loss_eur));document.getElementById('causeBars').innerHTML=C.map(x=>`<div class="barRow"><span class="name">${escapeHTML(x.issue_type)}</span><div class="barbg"><div class="fill" style="width:${(100*(+x.gross_loss_eur)/maxLoss).toFixed(1)}%"></div></div><span class="num">${compact(x.gross_loss_eur)}</span></div>`).join('');document.getElementById('controlOnly').textContent=number(C.find(x=>x.issue_type==='Approval fragmentation')?.flagged_payments);
function lineChart(data){const w=770,h=265,l=65,t=22,r=12,b=30,innerW=w-l-r,innerH=h-t-b,ys=[...data.map(d=>+d.gross_loss_eur),...data.map(d=>+d.modeled_recovery_eur)],ymax=Math.max(...ys)*1.13,x=i=>l+i*innerW/(data.length-1),y=v=>t+innerH*(1-v/ymax),grid=[0,.25,.5,.75,1].map(a=>`<line x1="${l}" y1="${y(ymax*a)}" x2="${w-r}" y2="${y(ymax*a)}" stroke="#354760" stroke-dasharray="4 5"/><text x="${l-12}" y="${y(ymax*a)+4}" text-anchor="end" fill="#8fa4bf" font-size="12">${compact(ymax*a)}</text>`).join(''),path=k=>data.map((d,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(+d[k]).toFixed(1)).join(' '),labels=data.filter((_,i)=>i%4===0||i===data.length-1).map(d=>{let i=data.indexOf(d);return `<text x="${x(i)}" y="${h-2}" text-anchor="middle" fill="#a9b9c9" font-size="11">${d.payment_month.slice(2)}</text>`}).join('');document.getElementById('trendChart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Monthly leakage and recoverability chart"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#4fe0b5" stop-opacity=".24"/><stop offset="1" stop-color="#4fe0b5" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${path('gross_loss_eur')} L${x(data.length-1)} ${h-b} L${x(0)} ${h-b} Z" fill="url(#fade)"/><path d="${path('gross_loss_eur')}" fill="none" stroke="#4fe0b5" stroke-width="3.5" stroke-linecap="round"/><path d="${path('modeled_recovery_eur')}" fill="none" stroke="#899bff" stroke-width="3" stroke-dasharray="6 4"/>${labels}</svg>`}lineChart(D.monthly);
function recalc(){const p=+document.getElementById('realization').value/100;document.getElementById('realizeLabel').textContent=Math.round(p*100)+'%';document.getElementById('scenarioValue').textContent=euros(m.modeled_recoverable_eur*p)}document.getElementById('realization').addEventListener('input',recalc);recalc();
document.getElementById('vendorRows').innerHTML=D.vendors.map(x=>`<tr><td>${escapeHTML(x.vendor_name)}</td><td>${escapeHTML(x.category)}</td><td>${escapeHTML(x.country)}</td><td>${number(x.payments)}</td><td class="money">${euros(x.gross_loss_eur)}</td><td>${euros(x.modeled_recovery_eur)}</td></tr>`).join('');
const issueFilter=document.getElementById('issueFilter');C.forEach(c=>{let option=document.createElement('option');option.value=c.issue_type;option.textContent=c.issue_type;issueFilter.appendChild(option)});function renderCases(){const q=document.getElementById('search').value.toLowerCase().trim(),filter=issueFilter.value;const out=D.cases.filter(x=>(filter==='all'||x.issue_type===filter)&&[x.payment_id,x.vendor_name,x.issue_type].some(s=>s.toLowerCase().includes(q)));document.getElementById('caseRows').innerHTML=out.map(x=>`<tr><td>${escapeHTML(x.payment_id)}</td><td>${escapeHTML(x.vendor_name)}</td><td><span class="pill">${escapeHTML(x.issue_type)}</span></td><td class="money">${euros(x.estimated_gross_loss_eur)}</td><td>${euros(x.modeled_recovery_eur)}</td><td>${escapeHTML(x.recommended_action)}</td></tr>`).join('')||'<tr><td colspan="6">No matching cases</td></tr>'}document.getElementById('search').addEventListener('input',renderCases);issueFilter.addEventListener('change',renderCases);renderCases();
</script></body></html>'''
page=page.replace('__PAYLOAD__',payload)
(ROOT/'dashboard/atlas_executive.html').write_text(page.replace('__OVERVIEW__','ProfitLeak_Atlas_Expert_iPhone.html'),encoding='utf-8')
(ROOT/'docs/explore.html').write_text(page.replace('__OVERVIEW__','index.html'),encoding='utf-8')
print('Self-contained dashboard: dashboard/atlas_executive.html')
